/* Civic Clarity: a role-aware public-sector learning workspace. Navy establishes trust, Bridge Teal marks capability, orange prompts the next service action, and violet identifies explainable intelligence. */
// The page intentionally uses compact heterogeneous configuration tuples for UI modules; runtime rendering is validated by the production build.
// @ts-nocheck
import * as React from "react";
import { useState } from "react";
import { toast } from "sonner";
import {
  ArrowRight, BarChart3, Bell, BookOpen, BriefcaseBusiness, Check, ChevronDown, CircleHelp, ClipboardCheck, FileCheck2, Filter, Gauge, GraduationCap, LayoutDashboard, LineChart, Menu, Search, Settings, ShieldCheck, Sparkles, Target, TrendingUp, UserRound, Upload, Users, X, BrainCircuit, SlidersHorizontal, Database, CalendarCheck, RefreshCw, Eye, EyeOff, LockKeyhole, Mail, ArrowUpRight, CheckCircle2,
} from "lucide-react";

const navItems = [
  { label: "Dashboard", icon: LayoutDashboard }, { label: "My Competencies", icon: Gauge }, { label: "Skill Gaps", icon: Target, badge: "3" }, { label: "Recommendations", icon: Sparkles }, { label: "Learning", icon: BookOpen }, { label: "Assessments", icon: ClipboardCheck }, { label: "Results", icon: LineChart }, { label: "Role Requirements", icon: BriefcaseBusiness }, { label: "Learning Evidence", icon: FileCheck2 }, { label: "Progress", icon: TrendingUp }, { label: "Profile", icon: UserRound },
];
const gaps = [{ name: "Python", domain: "Technical", current: 2.5, required: 4, priority: "High", color: "orange" }, { name: "Data Quality", domain: "Statistical", current: 3, required: 4, priority: "Medium", color: "teal" }, { name: "Statistical Analysis", domain: "Statistical", current: 3.2, required: 4, priority: "Medium", color: "violet" }];
const resources = [{ provider: "iGOT", title: "Python for Public Data Analysis", target: "Python · Data analysis", meta: "Intermediate · 6h 20m", score: "94.5%", tone: "navy" }, { provider: "NSSTA", title: "Data Quality Essentials", target: "Data Quality · Statistical", meta: "Foundational · 3h 45m", score: "87.2%", tone: "teal" }, { provider: "iGOT", title: "Making Evidence-Based Decisions", target: "Statistical Analysis", meta: "Intermediate · 4h 10m", score: "81.8%", tone: "violet" }];
const assessmentQuestions = ["Which approach best validates a public data set before publication?", "What does a confidence interval communicate in an official statistic?", "Which Python structure is best suited for labelled tabular data?"];

function ProgressBar({ value, color = "bg-teal" }: { value: number; color?: string }) { return <div className="h-2 w-full overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${color} transition-all duration-700`} style={{ width: `${value}%` }} /></div>; }
function Signal({ current, required }: { current: number; required: number }) { const c = current / 5 * 100; const r = required / 5 * 100; return <div className="signal-wrap"><div className="signal-track"><span className="signal-fill" style={{ width: `${c}%` }} /><span className="signal-required" style={{ left: `${r}%` }} /><span className="signal-current" style={{ left: `${c}%` }} /></div><div className="signal-legend"><span><i className="signal-dot signal-dot-current" />Current <b>{current}</b></span><span><i className="signal-dot signal-dot-required" />Required <b>{required}</b></span><span className="signal-gap">Gap <b>{(required-current).toFixed(1)}</b></span></div></div>; }
function Eyebrow({ children }: { children: React.ReactNode }) { return <div className="mb-2 text-[10px] font-bold uppercase tracking-[.14em] text-slate-400">{children}</div>; }
function PageHead({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: React.ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>{eyebrow}</Eyebrow><h1 className="font-display text-[36px] leading-[1.1] tracking-[-.04em] text-navy md:text-[44px]">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-500">{subtitle}</p></div>{action}</div>; }
function Pill({ children, tone = "teal" }: { children: React.ReactNode; tone?: string }) { return <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${tone === "orange" ? "bg-[#fff0e6] text-[#d96b27]" : tone === "violet" ? "bg-[#f0edfc] text-violet" : tone === "navy" ? "bg-[#eaf0f8] text-navy" : "bg-[#e8f6f3] text-teal"}`}>{children}</span>; }
function Card({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-2xl border border-[#dfe7f0] bg-white p-6 shadow-[0_7px_24px_rgba(18,48,87,.04)] md:p-7 ${className}`}>{children}</section>; }
function Action({ children, onClick, secondary = false }: { children: React.ReactNode; onClick?: () => void; secondary?: boolean }) { return <button onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-3 text-xs font-bold transition duration-200 active:scale-[.98] ${secondary ? "border border-slate-200 bg-white text-navy hover:bg-slate-50" : "bg-orange text-white shadow-[0_8px_18px_rgba(239,126,55,.2)] hover:-translate-y-0.5 hover:bg-[#f38b4e]"}`}>{children}</button>; }

function Dashboard({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Your capability overview" title={<>Good morning, Ananya<span className="text-orange">.</span></>} subtitle="Here’s where your current capability stands—and the clearest next step to keep growing in your role." action={<div className="flex items-center gap-3 rounded-xl border border-[#dce7ec] bg-white px-4 py-3 shadow-sm"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#edf7f5] text-teal"><BriefcaseBusiness size={17} /></div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Current role</div><div className="text-sm font-bold text-navy">Statistical Officer</div></div><ChevronDown size={16} className="ml-5 text-slate-400" /></div>} /><div className="workflow-strip mb-8"><div className="workflow-caption"><span className="h-2 w-2 rounded-full bg-orange" />Capability pathway</div><div className="workflow-steps"><span className="workflow-step active">Role</span><ArrowRight size={13} /><span className="workflow-step active">Assess</span><ArrowRight size={13} /><span className="workflow-step active">Find the gap</span><ArrowRight size={13} /><span className="workflow-step">Learn</span><ArrowRight size={13} /><span className="workflow-step">Show evidence</span></div></div><div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Current capability","72%","+8.4% since last review",Gauge,"teal"],["Priority skill gaps","03","1 high priority gap",Target,"orange"],["Learning progress","12 / 18","Resources completed",BookOpen,"violet"],["Capability improvement","+8.4%","vs. previous assessment",TrendingUp,"navy"]].map(([label,value,note,Icon,color]) => <Card key={String(label)} className="metric-card p-5"><div className="mb-5 flex items-start justify-between"><div className="text-[10px] font-bold uppercase tracking-[.13em] text-slate-400">{label}</div><div className={`flex h-8 w-8 items-center justify-center rounded-lg ${color === "teal" ? "bg-[#e9f7f4] text-teal" : color === "orange" ? "bg-[#fff2e8] text-orange" : color === "violet" ? "bg-[#f0edfc] text-violet" : "bg-[#eaf0f8] text-navy"}`}>{React.createElement(Icon as React.ElementType, { size: 16 })}</div></div><div className="text-[29px] font-extrabold tracking-[-.045em] text-navy">{value}</div><div className="mt-1 text-[11px] text-slate-400">{note}</div></Card>)}</div><div className="mb-8 grid gap-6 xl:grid-cols-[minmax(0,1.35fr)_minmax(360px,.75fr)]"><Card><div className="mb-6 flex items-start justify-between"><div><Eyebrow>Where to focus</Eyebrow><h2 className="text-[19px] font-bold text-navy">Priority skill gaps</h2></div><button onClick={() => go("Skill Gaps")} className="flex items-center gap-1 text-xs font-bold text-teal">View analysis <ArrowRight size={14} /></button></div><div className="space-y-4">{gaps.map(g => <div key={g.name} className="gap-row rounded-xl border border-slate-100 p-4 transition hover:-translate-y-0.5 hover:border-[#b9e1dc] hover:shadow-sm"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-3"><div className={`h-2.5 w-2.5 rounded-full ${g.color === "orange" ? "bg-orange" : g.color === "teal" ? "bg-teal" : "bg-violet"}`} /><div><div className="text-sm font-bold text-navy">{g.name}</div><div className="text-[11px] text-slate-400">{g.domain} competency</div></div></div><Pill tone={g.priority === "High" ? "orange" : "teal"}>{g.priority} priority</Pill></div><Signal current={g.current} required={g.required} /></div>)}</div></Card><div className="relative overflow-hidden rounded-2xl bg-navy p-6 text-white shadow-[0_12px_30px_rgba(18,48,87,.16)] md:p-7"><div className="absolute -right-10 -top-10 h-44 w-44 rounded-full border border-white/10" /><div className="relative"><Eyebrow>Your next best action</Eyebrow><h2 className="text-[19px] font-bold">Close your Python gap</h2><div className="my-7 flex items-center gap-4"><div className="flex h-[92px] w-[92px] items-center justify-center rounded-full" style={{ background: "conic-gradient(#28b7a7 0deg 340deg, rgba(255,255,255,.12) 340deg)" }}><div className="flex h-[72px] w-[72px] flex-col items-center justify-center rounded-full bg-navy"><span className="text-[21px] font-extrabold">94.5%</span><span className="text-[9px] text-slate-300">match score</span></div></div><div><div className="text-base font-bold leading-5">Python for Public<br />Data Analysis</div><div className="mt-2 text-[11px] text-slate-300"><Pill tone="navy">iGOT</Pill> <span className="ml-1">6h 20m · Intermediate</span></div></div></div><div className="mb-6 border-l-2 border-orange pl-4 text-xs leading-5 text-slate-300">This module targets your highest-priority gap and matches the responsibilities of your current role.</div><Action onClick={() => go("Learning")}>Start closing this gap <ArrowRight size={15} /></Action></div></div></div><div className="grid gap-6 xl:grid-cols-2"><Card><div className="mb-6 flex justify-between"><div><Eyebrow>Explainable intelligence</Eyebrow><h2 className="text-[19px] font-bold text-navy">Why this resource fits</h2></div><CircleHelp size={17} className="text-slate-400" /></div>{[["Competency match",40,"bg-teal"],["Gap priority",25,"bg-orange"],["Role match",20,"bg-navy"],["Difficulty match",10,"bg-violet"],["Prerequisite match",5,"bg-slate-300"]].map(([x,v,c]) => <div className="mb-4 flex items-center gap-4" key={String(x)}><div className="w-[125px] text-xs font-semibold text-slate-500">{x}</div><div className="flex-1"><ProgressBar value={Number(v)*2.5} color={String(c)} /></div><div className="w-8 text-right text-xs font-bold text-navy">{v}%</div></div>)}<div className="mt-6 rounded-xl border-l-2 border-teal bg-[#f4f8fb] p-4 text-xs leading-5 text-slate-500"><b className="text-navy">The bridge logic:</b> recommendations are ranked against your role, capability, and the gap that matters most now.</div></Card><Card><div className="mb-6"><Eyebrow>Keep the loop moving</Eyebrow><h2 className="text-[19px] font-bold text-navy">Continuous capability improvement</h2></div><div className="flex items-center justify-between py-5">{[[BookOpen,"Learn",true],[ClipboardCheck,"Evidence",true],[TrendingUp,"Update",false],[BarChart3,"Recalculate",false]].map(([Icon,label,on],i) => <div className="flex flex-1 items-center gap-1" key={String(label)}><div className="flex flex-col items-center gap-2"><div className={`flex h-11 w-11 items-center justify-center rounded-xl ${on ? "bg-[#e7f6f3] text-teal" : "bg-slate-100 text-slate-400"}`}>{React.createElement(Icon as React.ElementType, { size: 18 })}</div><span className={`text-[10px] font-bold ${on ? "text-navy" : "text-slate-400"}`}>{label}</span></div>{i<3 && <ArrowRight size={14} className="mx-auto mt-[-20px] text-slate-300" />}</div>)}</div><div className="mt-5 border-t border-slate-100 pt-5 text-xs leading-5 text-slate-500"><span className="font-bold text-teal">● Last assessment 14 Aug 2026</span><br />Complete your learning path to generate evidence and update your capability profile.</div></Card></div></>; }

function Competencies({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Capability profile" title="My Competencies" subtitle="Your role requirements and current capability, in one clear view." action={<Action onClick={() => go("AI Assessment")}><BrainCircuit size={15} /> Take AI competency assessment</Action>} /><Card><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-2"><Pill>All domains</Pill><Pill tone="navy">Needs improvement</Pill><Pill tone="violet">High priority</Pill></div><button className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-slate-500"><SlidersHorizontal size={14} /> Filter</button></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead className="border-y border-slate-100 text-[10px] uppercase tracking-[.12em] text-slate-400"><tr><th className="py-4">Competency framework</th><th>Domain</th><th>Current</th><th>Required</th><th>Gap</th><th>Status</th></tr></thead><tbody>{gaps.concat([{name:"Digital Governance",domain:"Governance",current:3.8,required:4,priority:"Low",color:"navy"}]).map(g => <tr key={g.name} className="border-b border-slate-50 text-xs"><td className="py-5 font-bold text-navy">{g.name}</td><td className="text-slate-500">{g.domain}</td><td className="font-bold text-navy">{g.current}</td><td className="text-slate-500">{g.required}</td><td className="font-bold text-orange">{(g.required-g.current).toFixed(1)}</td><td><Pill tone={g.priority === "High" ? "orange" : g.priority === "Low" ? "navy" : "teal"}>{g.priority === "Low" ? "On track" : g.priority === "High" ? "Needs improvement" : "Developing"}</Pill></td></tr>)}</tbody></table></div></Card></>; }
function SkillGaps({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Skill gap engine" title="Skill Gap Analysis" subtitle="Understand where your current capability differs from your role requirements." /><Card className="mb-6 bg-[#f9fbfd]"><div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><div className="step-circle">1</div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Role requirements</div><div className="font-bold text-navy">Statistical Officer framework</div></div></div><ArrowRight className="text-slate-300" /><div className="flex items-center gap-3"><div className="step-circle teal">2</div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Current capability</div><div className="font-bold text-navy">Latest AI assessment</div></div></div><ArrowRight className="text-slate-300" /><div className="flex items-center gap-3"><div className="step-circle orange">3</div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Gap priority</div><div className="font-bold text-navy">Learning action</div></div></div></div></Card><div className="space-y-4">{gaps.map(g => <Card key={g.name}><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-center"><div className="min-w-[180px]"><Pill tone={g.priority === "High" ? "orange" : "teal"}>{g.priority} priority</Pill><h2 className="mt-3 text-lg font-bold text-navy">{g.name}</h2><p className="mt-1 text-xs text-slate-500">Required for your current role responsibilities.</p></div><div className="flex-1 lg:max-w-[520px]"><Signal current={g.current} required={g.required} /></div><Action onClick={() => go("Recommendations")}>View learning <ArrowRight size={14} /></Action></div></Card>)}</div></>; }
function Recommendations({ go }: { go: (x: string) => void }) { const [provider, setProvider] = useState("All providers"); return <><PageHead eyebrow="Recommendation engine" title="Personalized Recommendations" subtitle="Learning resources ranked specifically for your role and skill gaps." action={<div className="flex gap-2"><Pill tone="teal">Competency match 40%</Pill><Pill tone="orange">Gap priority 25%</Pill></div>} /><Card className="mb-6"><div className="flex flex-wrap items-center gap-2"><Filter size={16} className="text-slate-400" />{["All providers","iGOT","NSSTA","High priority"].map(x => <button key={x} onClick={() => setProvider(x)} className={`rounded-lg px-3 py-2 text-xs font-bold ${provider===x ? "bg-[#e8f5f3] text-teal" : "text-slate-400 hover:bg-slate-50"}`}>{x}</button>)}</div><p className="mt-5 max-w-3xl text-xs leading-5 text-slate-500">Recommendations combine competency match, gap priority, role match, difficulty match, and prerequisite match. The reasoning is visible so every next step is understandable.</p></Card><div className="grid gap-5 lg:grid-cols-3">{resources.filter(r => provider === "All providers" || provider === r.provider || provider === "High priority").map(r => <Card key={r.title} className="flex flex-col"><div className="mb-6 flex justify-between"><Pill tone={r.tone}>{r.provider}</Pill><span className="flex items-center gap-1 text-xs font-bold text-teal"><TrendingUp size={13} />{r.score}</span></div><h2 className="text-lg font-bold leading-6 text-navy">{r.title}</h2><p className="mt-3 text-xs text-slate-500">Targets: {r.target}</p><p className="mt-1 text-xs text-slate-400">{r.meta}</p><div className="mt-6 border-l-2 border-orange pl-3 text-xs leading-5 text-slate-500">Matches your skill gap and is appropriate for your current capability.</div><div className="mt-auto flex gap-2 pt-7"><Action onClick={() => go("Learning")}>Start learning <ArrowRight size={14} /></Action><Action secondary onClick={() => toast("Recommendation details opened.")}>Details</Action></div></Card>)}</div></>; }
function Learning({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Focused learning" title="Learning" subtitle="A distraction-free path to improve the competency that matters next." action={<Pill tone="navy">iGOT course module</Pill>} /><div className="grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><Card><div className="mb-6 flex items-center justify-between"><div><Eyebrow>Current resource</Eyebrow><h2 className="text-2xl font-bold text-navy">Python for Public Data Analysis</h2><p className="mt-2 text-xs text-slate-500">Improve Python capability from 2.5 toward required level 4.0.</p></div><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e7f6f3] text-teal"><BookOpen size={24} /></div></div><ProgressBar value={38} /><div className="mt-2 flex justify-between text-xs font-bold text-slate-400"><span>38% complete</span><span>2h 25m remaining</span></div><div className="mt-8 flex border-b border-slate-100">{["Overview","Learning material","Practice","Assessment"].map((x,i) => <button key={x} className={`border-b-2 px-4 py-3 text-xs font-bold ${i===0 ? "border-teal text-teal" : "border-transparent text-slate-400"}`}>{x}</button>)}</div><div className="mt-7 rounded-xl bg-[#f7fafc] p-5"><Eyebrow>Learning objective</Eyebrow><p className="text-sm leading-6 text-navy">Prepare, validate, and interpret public datasets with reproducible Python workflows.</p></div><div className="mt-6 flex justify-between"><Action onClick={() => toast("Learning material opened.")}>Continue learning <ArrowRight size={14} /></Action><button onClick={() => go("Quiz Studio")} className="text-xs font-bold text-teal">Generate practice quiz</button></div></Card><Card><Eyebrow>Capability target</Eyebrow><div className="mt-4 space-y-5"><div><div className="mb-2 flex justify-between text-xs font-bold"><span className="text-slate-500">Current capability</span><span className="text-navy">2.5</span></div><ProgressBar value={50} color="bg-orange" /></div><div><div className="mb-2 flex justify-between text-xs font-bold"><span className="text-slate-500">Target capability</span><span className="text-navy">4.0</span></div><ProgressBar value={80} color="bg-teal" /></div></div><div className="mt-8 border-t border-slate-100 pt-6"><div className="flex items-center gap-2 text-xs font-bold text-teal"><ShieldCheck size={16} /> Evidence will update your profile</div><p className="mt-2 text-xs leading-5 text-slate-500">Complete practice and assessment to generate measurable learning evidence.</p></div></Card></div></>; }
function Evidence({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Proof of learning" title="Learning Evidence" subtitle="See how learning activities become evidence and update your capability profile." action={<Action onClick={() => go("Learning")}>Continue learning <ArrowRight size={14} /></Action>} /><Card className="mb-6"><div className="flex flex-wrap items-center justify-between gap-3"><div className="workflow-steps"><span className="workflow-step active">Learn</span><ArrowRight size={13} /><span className="workflow-step active">Practice</span><ArrowRight size={13} /><span className="workflow-step active">Assess</span><ArrowRight size={13} /><span className="workflow-step active">Evidence</span><ArrowRight size={13} /><span className="workflow-step">Capability update</span></div><Pill>2 evidence items this month</Pill></div></Card><div className="grid gap-5 md:grid-cols-2"><Card><div className="flex items-start justify-between"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#e7f6f3] text-teal"><ClipboardCheck size={20} /></div><Pill>14 Aug 2026</Pill></div><h2 className="mt-5 text-lg font-bold text-navy">Python Assessment</h2><p className="mt-2 text-xs text-slate-500">Assessment · Python competency</p><div className="mt-6 flex items-end justify-between"><div><div className="text-3xl font-extrabold text-navy">82%</div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Assessment score</div></div><Check className="text-teal" /></div></Card><Card className="border-teal/30 bg-[#f4fbf9]"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-white text-teal"><RefreshCw size={20} /></div><h2 className="mt-5 text-lg font-bold text-navy">Capability profile updated</h2><p className="mt-2 text-xs leading-5 text-slate-500">Your Python capability moved from 2.5 to 3.2 after the latest evidence was reviewed.</p><div className="mt-6"><ProgressBar value={64} /></div><div className="mt-2 text-xs font-bold text-teal">+0.7 improvement</div></Card></div></>; }
function Progress({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Capability growth" title="Progress" subtitle="Track how learning activity reduces gaps and builds capability over time." /><div className="mb-6 grid gap-4 md:grid-cols-3">{[["Resources completed","12","of 18",BookOpen],["Assessments completed","04","this quarter",ClipboardCheck],["Evidence generated","08","verified items",FileCheck2]].map(([a,b,c,I]) => <Card key={String(a)} className="p-5">{React.createElement(I as React.ElementType, { className: "mb-5 text-teal", size: 19 })}<div className="text-2xl font-extrabold text-navy">{b}</div><div className="mt-1 text-xs font-bold text-slate-500">{a}</div><div className="mt-1 text-[11px] text-slate-400">{c}</div></Card>)}</div><div className="grid gap-6 xl:grid-cols-2"><Card><Eyebrow>Capability growth</Eyebrow><h2 className="mb-7 text-lg font-bold text-navy">Before → after</h2>{[["Python",2.5,3.2],["Data Analysis",3,3.6],["Data Quality",2.8,3.7]].map(([name,before,after]) => <div className="mb-6" key={String(name)}><div className="mb-2 flex justify-between text-xs font-bold"><span className="text-navy">{name}</span><span className="text-teal">{before} → {after}</span></div><ProgressBar value={Number(after)*20} /></div>)}</Card><Card><Eyebrow>Next priority</Eyebrow><h2 className="text-lg font-bold text-navy">Continue improving Python</h2><p className="mt-3 text-sm leading-6 text-slate-500">You have reduced your Python gap by 0.7 points. One more learning module and an assessment will move this competency closer to the role requirement.</p><div className="mt-6"><Action onClick={() => go("Recommendations")}>See next learning action <ArrowRight size={14} /></Action></div></Card></div></>; }
function Profile() { return <><PageHead eyebrow="Employee profile" title="Profile" subtitle="Your identity, role context, and learning preferences." /><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Card><div className="flex items-center gap-4"><div className="flex h-16 w-16 items-center justify-center rounded-full bg-[#f6d5b5] text-lg font-bold text-[#7d4725]">AM</div><div><h2 className="text-xl font-bold text-navy">Ananya Mehta</h2><p className="text-xs text-slate-500">Employee ID · GOV-28417</p></div></div><div className="mt-8 space-y-5 border-t border-slate-100 pt-6">{[["Department","Ministry of Statistics"],["Designation","Statistical Officer"],["Assigned role","Statistical Officer · Level 4"]].map(([a,b]) => <div key={a}><Eyebrow>{a}</Eyebrow><div className="text-sm font-bold text-navy">{b}</div></div>)}</div></Card><Card><Eyebrow>Role context</Eyebrow><h2 className="text-lg font-bold text-navy">Required competencies</h2><div className="mt-5 flex flex-wrap gap-2">{["Python","Statistical Analysis","Data Quality","Digital Governance","Evidence-based decisions"].map(x => <Pill key={x} tone="navy">{x}</Pill>)}</div><div className="mt-8 border-t border-slate-100 pt-6"><Eyebrow>Learning preferences</Eyebrow><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-[#f7fafc] p-4 text-xs font-bold text-navy">Short practical modules<br /><span className="font-medium text-slate-400">30–90 minute sessions</span></div><div className="rounded-xl bg-[#f7fafc] p-4 text-xs font-bold text-navy">Applied assessments<br /><span className="font-medium text-slate-400">Evidence-led progress</span></div></div></div></Card></div></>; }
function ProfileManagement() { const [editing, setEditing] = useState(false); const [saving, setSaving] = useState(false); const save = () => { setSaving(true); setTimeout(() => { setSaving(false); setEditing(false); toast("Profile changes saved. Connect to PUT /api/v1/users/me."); }, 650); }; return <><PageHead eyebrow="Employee profile" title="Profile" subtitle="Manage editable employee information while protected account fields remain read-only." action={editing ? <Action onClick={save}>{saving ? <RefreshCw className="animate-spin" size={14} /> : <Check size={14} />} Save profile</Action> : <Action secondary onClick={() => setEditing(true)}>Edit profile</Action>} /><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Card><div className="flex items-center gap-4"><div className="flex h-16 w-16 items-center justify-center rounded-full bg-[#f6d5b5] text-lg font-bold text-[#7d4725]">AM</div><div><h2 className="text-xl font-bold text-navy">Ananya Mehta</h2><p className="text-xs text-slate-500">Employee ID · GOV-28417</p></div></div><div className="mt-8 border-t border-slate-100 pt-6"><Eyebrow>Account status</Eyebrow><div className="flex items-center gap-2 text-sm font-bold text-teal"><span className="h-2 w-2 rounded-full bg-teal" />Active employee</div><div className="mt-5"><Eyebrow>Access role</Eyebrow><Pill tone="navy">EMPLOYEE</Pill></div></div></Card><Card><div className="mb-6 flex items-center justify-between"><div><Eyebrow>{editing ? "Editable information" : "Profile information"}</Eyebrow><h2 className="text-lg font-bold text-navy">Employee details</h2></div><UserRound className="text-teal" size={20} /></div><div className="grid gap-4 sm:grid-cols-2">{[["Email address","ananya.mehta@department.gov.in",false],["Full name","Ananya Mehta",true],["Employee ID","GOV-28417",true],["Designation","Statistical Officer",true],["Department","Ministry of Statistics",true],["Professional role","Statistical Officer",false]].map(([label,value,editable]) => <label className="text-xs font-bold text-navy" key={label}>{label}<input className={`form-input ${!editable ? "bg-slate-50 text-slate-400" : ""}`} defaultValue={value as string} disabled={!editing || !editable} /></label>)}</div><div className="mt-7 rounded-xl border-l-2 border-teal bg-[#f4f8fb] p-4 text-xs leading-5 text-slate-500">Email, professional role, access role, and active status are controlled by the authenticated backend and cannot be edited here.</div></Card></div></>; }
function AIAssessment() { return <><PageHead eyebrow="AI competency assessment" title="Assess your capability" subtitle="A role-aware assessment generated from your competency framework and current learning evidence." action={<Pill tone="violet">AI-assisted · reviewable</Pill>} /><div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><Card><div className="mb-7 flex items-center justify-between"><div><Eyebrow>Assessment readiness</Eyebrow><h2 className="text-xl font-bold text-navy">Statistical Officer competency check</h2></div><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#f0edfc] text-violet"><BrainCircuit size={21} /></div></div><div className="space-y-4">{[["Role framework","Statistical Officer · Level 4",true],["Competencies covered","Python, data quality, statistical analysis",true],["Estimated time","18 minutes",false],["Evidence created","Capability update after review",false]].map(([a,b,on]) => <div className="flex items-center gap-3 rounded-xl bg-[#f7fafc] p-4" key={String(a)}><div className={`flex h-8 w-8 items-center justify-center rounded-lg ${on ? "bg-[#e7f6f3] text-teal" : "bg-white text-slate-400"}`}>{on ? <Check size={15} /> : <CalendarCheck size={15} />}</div><div><div className="text-xs font-bold text-navy">{a}</div><div className="mt-1 text-[11px] text-slate-500">{b}</div></div></div>)}</div><div className="mt-7 flex gap-2"><Action onClick={() => toast("Assessment started. Backend question flow is ready to connect.")}>Begin assessment <ArrowRight size={14} /></Action><Action secondary onClick={() => toast("Assessment guide opened.")}>View guide</Action></div></Card><Card><Eyebrow>How it works</Eyebrow><h2 className="text-lg font-bold text-navy">Measure capability, not attendance</h2><div className="mt-6 space-y-5">{[["01","Role-aware questions","Questions are aligned to the competency level required by your role."],["02","AI-assisted scoring","Responses are evaluated against the capability framework for review."],["03","Gap recalculation","Results update your skill gaps and learning priorities."]].map(([n,t,d]) => <div className="flex gap-4" key={n}><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-navy text-[10px] font-bold text-white">{n}</div><div><div className="text-sm font-bold text-navy">{t}</div><div className="mt-1 text-xs leading-5 text-slate-500">{d}</div></div></div>)}</div></Card></div></>; }
function QuizStudio() { const [uploaded, setUploaded] = useState(false); return <><PageHead eyebrow="AI learning studio" title="Generate a practice quiz" subtitle="Upload learning content and create reviewable MCQs and quizzes for employees." action={<Pill tone="violet">AI-powered content generation</Pill>} /><div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><Card><div className="mb-6"><Eyebrow>1 · Source content</Eyebrow><h2 className="text-lg font-bold text-navy">Upload learning material</h2><p className="mt-2 text-xs leading-5 text-slate-500">The generated questions will stay tied to the uploaded material for reviewer validation.</p></div><button onClick={() => setUploaded(true)} className={`flex w-full flex-col items-center justify-center rounded-2xl border-2 border-dashed p-10 text-center transition ${uploaded ? "border-teal bg-[#f4fbf9]" : "border-slate-200 hover:border-teal hover:bg-[#f8fcfb]"}`}><div className={`mb-4 flex h-12 w-12 items-center justify-center rounded-xl ${uploaded ? "bg-teal text-white" : "bg-[#eaf0f8] text-navy"}`}>{uploaded ? <Check size={21} /> : <Upload size={21} />}</div><div className="text-sm font-bold text-navy">{uploaded ? "Public-data-analysis.pdf uploaded" : "Choose PDF, DOCX, or PPTX"}</div><div className="mt-2 text-xs text-slate-400">{uploaded ? "Ready to generate questions" : "Maximum 25 MB"}</div></button><div className="mt-7"><Eyebrow>2 · Quiz settings</Eyebrow><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-slate-200 p-3 text-xs font-bold text-navy">10 questions <ChevronDown className="float-right" size={14} /></div><div className="rounded-xl border border-slate-200 p-3 text-xs font-bold text-navy">Intermediate <ChevronDown className="float-right" size={14} /></div></div></div><Action onClick={() => toast(uploaded ? "Quiz generation queued for review." : "Upload learning content first.")} >Generate MCQ quiz <Sparkles size={14} /></Action></Card><Card><div className="mb-6 flex justify-between"><div><Eyebrow>3 · Review generated questions</Eyebrow><h2 className="text-lg font-bold text-navy">MCQ preview</h2></div><Pill tone="navy">Draft · Review required</Pill></div>{assessmentQuestions.map((q,i) => <div className="mb-4 rounded-xl border border-slate-100 p-4" key={q}><div className="flex gap-3"><span className="text-xs font-extrabold text-teal">0{i+1}</span><div className="text-xs font-bold leading-5 text-navy">{q}<div className="mt-3 grid gap-2 text-[11px] font-medium text-slate-500 sm:grid-cols-2"><span className="rounded-lg bg-[#f7fafc] p-2">A · Data profiling</span><span className="rounded-lg bg-[#f7fafc] p-2">B · Data validation</span><span className="rounded-lg bg-[#f7fafc] p-2">C · Random sampling</span><span className="rounded-lg bg-[#f7fafc] p-2">D · Data export</span></div></div></div></div>)}<div className="rounded-xl border-l-2 border-orange bg-[#fffaf6] p-4 text-xs leading-5 text-slate-500"><b className="text-navy">Human review stays in the loop.</b> Administrators can edit, approve, or discard generated questions before publishing.</div></Card></div></>; }
function AdminDashboard({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Administrator workspace" title="Capability operations" subtitle="Monitor learner capability, assessment activity, learning adoption, and content intelligence across the department." action={<Pill tone="navy"><Users size={13} /> Administrator</Pill>} /><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Employees covered","1,284","+6.2% this quarter",Users],["Assessments completed","842","65.6% coverage",ClipboardCheck],["Priority gaps","216","Across 96 employees",Target],["Evidence generated","1,967","+18% this month",FileCheck2]].map(([a,b,c,I]) => <Card className="p-5" key={String(a)}>{React.createElement(I as React.ElementType, { className: "mb-5 text-teal", size: 19 })}<div className="text-2xl font-extrabold text-navy">{b}</div><div className="mt-1 text-xs font-bold text-slate-500">{a}</div><div className="mt-1 text-[11px] text-slate-400">{c}</div></Card>)}</div><div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><Card><div className="mb-7 flex justify-between"><div><Eyebrow>Department health</Eyebrow><h2 className="text-lg font-bold text-navy">Competency coverage by domain</h2></div><BarChart3 className="text-teal" size={19} /></div>{[["Statistical",82,"bg-teal"],["Technical",64,"bg-orange"],["Digital Governance",76,"bg-violet"],["Behavioural / Managerial",58,"bg-navy"]].map(([x,v,c]) => <div className="mb-6" key={String(x)}><div className="mb-2 flex justify-between text-xs font-bold"><span className="text-slate-500">{x}</span><span className="text-navy">{v}%</span></div><ProgressBar value={Number(v)} color={String(c)} /></div>)}</Card><Card><div className="mb-7"><Eyebrow>Administrator actions</Eyebrow><h2 className="text-lg font-bold text-navy">Keep the system useful</h2></div><div className="space-y-3">{[[BrainCircuit,"Review AI assessments","18 awaiting validation","AI Assessment"],[Sparkles,"Approve recommendations","6 provider mappings updated","Recommendations"],[Upload,"Generate quizzes","3 content packs ready","Quiz Studio"]].map(([I,t,d,target]) => <button onClick={() => go(String(target))} className="flex w-full items-center gap-3 rounded-xl border border-slate-100 p-4 text-left transition hover:-translate-y-0.5 hover:border-[#b9e1dc] hover:shadow-sm" key={String(t)}><div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#edf7f5] text-teal">{React.createElement(I as React.ElementType, { size: 18 })}</div><div className="flex-1"><div className="text-xs font-bold text-navy">{t}</div><div className="mt-1 text-[11px] text-slate-400">{d}</div></div><ArrowRight size={15} className="text-slate-300" /></button>)}</div></Card></div><Card className="mt-6"><div className="mb-5 flex items-center justify-between"><div><Eyebrow>Integration readiness</Eyebrow><h2 className="text-lg font-bold text-navy">Learning provider connections</h2></div><Database className="text-teal" size={19} /></div><div className="grid gap-3 md:grid-cols-3">{[["iGOT","Course modules","Connected",true],["NSSTA","TPAC programmes","Connected",true],["Assessment service","AI scoring endpoint","Ready for backend",false]].map(([a,b,c,on]) => <div className="rounded-xl bg-[#f7fafc] p-4" key={String(a)}><div className="flex items-center justify-between"><span className="text-sm font-bold text-navy">{a}</span><span className={`h-2 w-2 rounded-full ${on ? "bg-teal" : "bg-orange"}`} /></div><div className="mt-2 text-xs text-slate-500">{b}</div><div className="mt-3 text-[10px] font-bold uppercase tracking-[.1em] text-teal">{c}</div></div>)}</div></Card></>; }

function LandingPage({ onSuccess, onRegister }: { onSuccess: () => void; onRegister: () => void }) { const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [showPassword, setShowPassword] = useState(false); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const submit = () => { if (!email.trim() || !password.trim()) { setError("Enter your official email address and password to continue."); return; } if (!email.includes("@")) { setError("Enter a valid department email address."); return; } setError(""); setLoading(true); setTimeout(() => { window.localStorage.setItem("shikshasetu_demo_token", "jwt-ready"); setLoading(false); onSuccess(); }, 700); }; return <div className="landing-page min-h-screen bg-[#f7fafc] text-ink"><header className="sticky top-0 z-30 border-b border-[#dfe7f0]/80 bg-[#f7fafc]/90 backdrop-blur-xl"><div className="mx-auto flex max-w-[1240px] items-center justify-between px-5 py-4 md:px-8"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-navy shadow-[0_8px_18px_rgba(18,48,87,.18)]"><img src="/manus-storage/shikshasetu-bridge-mark_0aca95ee.png" alt="" className="h-7 w-7" /></div><div><div className="text-[17px] font-extrabold tracking-[-.04em] text-navy">ShikshaSetu</div><div className="text-[9px] font-bold uppercase tracking-[.18em] text-slate-400">Capability Intelligence</div></div></div><nav className="hidden items-center gap-7 text-xs font-bold text-slate-500 md:flex"><a href="#how-it-works" className="transition hover:text-teal">How it works</a><a href="#capabilities" className="transition hover:text-teal">Capabilities</a><a href="#providers" className="transition hover:text-teal">Learning ecosystem</a></nav><a href="#sign-in" className="rounded-full border border-[#cfe3e3] bg-white px-4 py-2 text-xs font-bold text-teal shadow-sm transition hover:-translate-y-0.5 hover:border-teal">Sign in <ArrowRight className="ml-1 inline" size={13} /></a></div></header><main><section className="landing-hero relative overflow-hidden"><div className="landing-orb landing-orb-one" /><div className="landing-orb landing-orb-two" /><div className="mx-auto grid max-w-[1240px] items-center gap-12 px-5 py-16 md:px-8 md:py-24 lg:grid-cols-[1.05fr_.95fr] lg:gap-16"><div className="relative"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-[#cfe3e3] bg-white/70 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[.14em] text-teal"><span className="h-2 w-2 rounded-full bg-orange" />Built for public-service capability growth</div><h1 className="max-w-[650px] font-display text-[46px] leading-[.98] tracking-[-.045em] text-navy md:text-[70px]">Turn every learning step into <span className="text-teal">capability.</span></h1><p className="mt-7 max-w-[560px] text-base leading-7 text-slate-500 md:text-lg">ShikshaSetu helps employees understand their role requirements, measure competency with confidence, and follow a learning path built around the gap that matters next.</p><div className="mt-8 flex flex-wrap gap-3"><a href="#capabilities" className="rounded-xl bg-orange px-5 py-3 text-xs font-bold text-white shadow-[0_12px_24px_rgba(239,126,55,.2)] transition hover:-translate-y-0.5 hover:bg-[#f38b4e]">Explore the capability model <ArrowRight className="ml-1 inline" size={14} /></a><a href="#how-it-works" className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-xs font-bold text-navy transition hover:border-teal hover:text-teal">See how it works</a></div><div className="mt-12 flex flex-wrap gap-8 border-t border-[#dfe7f0] pt-6"><div><div className="text-2xl font-extrabold text-navy">33</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[.1em] text-slate-400">Competencies mapped</div></div><div><div className="text-2xl font-extrabold text-navy">4</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[.1em] text-slate-400">Capability domains</div></div><div><div className="text-2xl font-extrabold text-navy">1</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[.1em] text-slate-400">Clear next step</div></div></div></div><div id="sign-in" className="relative scroll-mt-28"><div className="absolute -inset-3 rounded-[30px] bg-[#d9eeeb] blur-2xl opacity-60" /><div className="relative rounded-[26px] border border-[#dbe7ef] bg-white p-7 shadow-[0_24px_65px_rgba(18,48,87,.14)] md:p-9"><div className="mb-7 flex items-start justify-between"><div><Eyebrow>Employee access</Eyebrow><h2 className="mt-1 font-display text-3xl text-navy">Sign in to your workspace</h2><p className="mt-2 text-xs leading-5 text-slate-500">Your role, your gaps, your next step.</p></div><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#e8f6f3] text-teal"><LockKeyhole size={20} /></div></div>{error && <div role="alert" className="mb-5 rounded-xl border border-red-200 bg-red-50 p-3 text-xs leading-5 text-red-700">{error}</div>}<div className="space-y-4"><label className="block text-xs font-bold text-navy">Email address<div className="relative"><Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input className="form-input pl-10" value={email} onChange={e => setEmail(e.target.value)} type="email" autoComplete="email" placeholder="name@department.gov.in" /></div></label><label className="block text-xs font-bold text-navy">Password<div className="relative"><LockKeyhole className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input className="form-input pl-10 pr-11" value={password} onChange={e => setPassword(e.target.value)} type={showPassword ? "text" : "password"} autoComplete="current-password" placeholder="Enter your password" /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-navy" aria-label={showPassword ? "Hide password" : "Show password"}>{showPassword ? <EyeOff size={16} /> : <Eye size={16} />}</button></div></label></div><div className="mt-4 flex justify-end"><button type="button" onClick={() => toast("Password recovery is ready to connect to the authentication service.")} className="text-xs font-bold text-teal">Forgot password?</button></div><button onClick={submit} disabled={loading} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-orange px-4 py-3.5 text-xs font-bold text-white shadow-[0_10px_20px_rgba(239,126,55,.2)] transition hover:-translate-y-0.5 hover:bg-[#f38b4e] active:scale-[.98] disabled:opacity-60">{loading ? <RefreshCw className="animate-spin" size={15} /> : <ShieldCheck size={15} />}{loading ? "Checking your access…" : "Sign in securely"}<ArrowRight size={15} /></button><div className="mt-5 text-center text-xs text-slate-500">New employee? <button onClick={onRegister} className="font-bold text-teal">Create an account</button></div><div className="mt-6 flex items-start gap-2 border-t border-slate-100 pt-5 text-[10px] leading-5 text-slate-400"><CheckCircle2 className="mt-0.5 shrink-0 text-teal" size={14} />Protected employee session ready for JWT and Bearer authorization.</div></div></div></div></section><section id="how-it-works" className="scroll-mt-20 border-y border-[#dfe7f0] bg-white"><div className="mx-auto max-w-[1240px] px-5 py-16 md:px-8 md:py-20"><div className="max-w-[620px]"><Eyebrow>The ShikshaSetu method</Eyebrow><h2 className="mt-2 font-display text-4xl leading-tight text-navy md:text-5xl">A clearer bridge from role to readiness.</h2><p className="mt-4 text-sm leading-6 text-slate-500">The experience is designed around a simple public-service question: what capability should I build next, and how will I know I have built it?</p></div><div className="mt-12 grid gap-5 md:grid-cols-3">{[["01","Understand the role","See the competency levels your professional role requires."],["02","Measure the gap","Combine self-rating, knowledge, scenarios, and training evidence."],["03","Act with confidence","Follow explainable iGOT and NSSTA learning recommendations."]].map(([n,t,d]) => <div className="landing-step" key={n}><div className="text-sm font-extrabold text-orange">{n}</div><h3 className="mt-8 text-lg font-bold text-navy">{t}</h3><p className="mt-3 text-sm leading-6 text-slate-500">{d}</p><ArrowUpRight className="mt-8 text-teal" size={19} /></div>)}</div></div></section><section id="capabilities" className="scroll-mt-20 bg-[#eef5f8]"><div className="mx-auto max-w-[1240px] px-5 py-16 md:px-8 md:py-20"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>One connected capability model</Eyebrow><h2 className="mt-2 font-display text-4xl text-navy md:text-5xl">Made for meaningful progress.</h2></div><p className="max-w-[360px] text-sm leading-6 text-slate-500">Every screen connects assessment, gap analysis, learning, evidence, and results into one continuous experience.</p></div><div className="mt-10 grid gap-4 md:grid-cols-2 lg:grid-cols-4">{[[BrainCircuit,"AI competency assessment","Role-aware assessment across self-rating, MCQ, scenario, and evidence."],[Target,"Automated skill-gap analysis","Current versus required capability with priority signals."],[Sparkles,"Personalized learning","iGOT modules and NSSTA TPAC programmes matched to the gap."],[Upload,"AI quiz generation","Create reviewable MCQs and quizzes from uploaded learning content."]].map(([I,t,d]) => <div className="rounded-2xl border border-[#dbe7ef] bg-white p-5 shadow-sm transition hover:-translate-y-1 hover:shadow-md" key={String(t)}><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#e8f6f3] text-teal">{React.createElement(I as React.ElementType, { size: 20 })}</div><h3 className="mt-5 text-sm font-bold text-navy">{t}</h3><p className="mt-2 text-xs leading-5 text-slate-500">{d}</p></div>)}</div></div></section><section id="providers" className="scroll-mt-20 bg-navy text-white"><div className="mx-auto flex max-w-[1240px] flex-col justify-between gap-10 px-5 py-16 md:px-8 md:py-20 lg:flex-row lg:items-center"><div className="max-w-[640px]"><Eyebrow>Learning ecosystem</Eyebrow><h2 className="mt-2 font-display text-4xl leading-tight md:text-5xl">One pathway. The right provider at the right moment.</h2><p className="mt-5 text-sm leading-6 text-slate-300">Bring iGOT course modules and NSSTA’s TPAC recommended training programmes into the same recommendation layer, with clear reasoning for every suggested action.</p></div><div className="grid w-full max-w-[380px] gap-3 sm:grid-cols-2"><div className="rounded-2xl border border-white/10 bg-white/5 p-5"><div className="text-2xl font-extrabold text-white">iGOT</div><div className="mt-2 text-xs text-slate-300">Course modules connected to competency gaps.</div></div><div className="rounded-2xl border border-white/10 bg-white/5 p-5"><div className="text-2xl font-extrabold text-white">NSSTA</div><div className="mt-2 text-xs text-slate-300">TPAC recommended programmes for applied growth.</div></div></div></div></section></main><footer className="border-t border-[#dfe7f0] bg-white"><div className="mx-auto flex max-w-[1240px] flex-col justify-between gap-3 px-5 py-6 text-[10px] text-slate-400 sm:flex-row md:px-8"><span>© ShikshaSetu Capability Intelligence</span><span>For government employees and learning administrators</span></div></footer></div>; }
function LoginPage({ onSuccess, onRegister }: { onSuccess: () => void; onRegister: () => void }) { const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [showPassword, setShowPassword] = useState(false); const [remember, setRemember] = useState(true); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const submit = () => { if (!email.trim() || !password.trim()) { setError("Enter your official email address and password to continue."); return; } if (!email.includes("@")) { setError("Enter a valid department email address."); return; } setError(""); setLoading(true); window.localStorage.setItem("shikshasetu_remember", String(remember)); setTimeout(() => { window.localStorage.setItem("shikshasetu_demo_token", "jwt-ready"); setLoading(false); onSuccess(); }, 700); }; return <div className="login-page min-h-screen bg-[#eef4f8] px-5 py-6 md:px-10 md:py-8"><div className="mx-auto flex max-w-[1180px] items-center justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-navy shadow-[0_8px_18px_rgba(18,48,87,.18)]"><img src="/manus-storage/shikshasetu-bridge-mark_0aca95ee.png" alt="" className="h-7 w-7" /></div><div><div className="text-[16px] font-extrabold tracking-[-.04em] text-navy">ShikshaSetu</div><div className="text-[9px] font-bold uppercase tracking-[.18em] text-slate-400">Capability Intelligence</div></div></div><div className="hidden items-center gap-2 text-xs font-semibold text-slate-500 sm:flex"><ShieldCheck size={15} className="text-teal" /> Protected employee access</div></div><div className="mx-auto mt-8 grid max-w-[1180px] overflow-hidden rounded-[28px] border border-[#d9e4ec] bg-white shadow-[0_24px_70px_rgba(18,48,87,.12)] lg:mt-12 lg:grid-cols-[.93fr_1.07fr]"><div className="login-story relative overflow-hidden bg-navy p-8 text-white md:p-12"><div className="absolute -right-24 -top-24 h-80 w-80 rounded-full border border-white/10" /><div className="absolute -bottom-24 -left-24 h-64 w-64 rounded-full border border-teal/20" /><div className="relative flex h-full flex-col"><div className="mb-16 flex items-center justify-between"><span className="rounded-full border border-white/15 px-3 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-slate-300">Government employee workspace</span><ArrowUpRight className="text-orange" size={18} /></div><div className="max-w-[430px]"><div className="mb-4 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.14em] text-teal-200"><span className="h-2 w-2 rounded-full bg-orange" /> Your next capability</div><h1 className="font-display text-[38px] leading-[1.06] tracking-[-.035em] md:text-[51px]">The right next step starts with knowing your gap.</h1><p className="mt-6 max-w-[390px] text-sm leading-6 text-slate-300">Sign in to see the competencies your role requires, the learning that fits, and the evidence that proves progress.</p></div><div className="mt-auto pt-16"><div className="mb-3 text-[10px] font-bold uppercase tracking-[.13em] text-slate-400">Your capability pathway</div><div className="login-pathway"><div className="login-path-line" /><div><span className="login-path-dot done" /><b>Role</b></div><div><span className="login-path-dot done" /><b>Assess</b></div><div><span className="login-path-dot" /><b>Learn</b></div><div><span className="login-path-dot" /><b>Evidence</b></div></div><div className="mt-6 flex flex-wrap gap-2"><Pill tone="navy">33 competencies</Pill><Pill tone="navy">iGOT + NSSTA</Pill><Pill tone="navy">Evidence-led</Pill></div></div></div></div><div className="p-8 md:p-12 lg:p-16"><div className="max-w-[470px]"><Eyebrow>Secure employee access</Eyebrow><h2 className="font-display text-[34px] leading-tight tracking-[-.035em] text-navy">Sign in to your workspace</h2><p className="mt-3 text-sm leading-6 text-slate-500">Continue your capability journey from the last saved assessment.</p>{error && <div role="alert" className="mt-6 flex items-start gap-2 rounded-xl border border-red-200 bg-red-50 p-3 text-xs leading-5 text-red-700"><CircleHelp className="mt-0.5 shrink-0" size={15} />{error}</div>}<div className="mt-8 space-y-5"><label className="block text-xs font-bold text-navy">Email address<div className="relative"><Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input className="form-input pl-10" value={email} onChange={e => setEmail(e.target.value)} type="email" autoComplete="email" placeholder="name@department.gov.in" /></div></label><label className="block text-xs font-bold text-navy">Password<div className="relative"><LockKeyhole className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input className="form-input pl-10 pr-11" value={password} onChange={e => setPassword(e.target.value)} type={showPassword ? "text" : "password"} autoComplete="current-password" placeholder="Enter your password" /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-navy" aria-label={showPassword ? "Hide password" : "Show password"}>{showPassword ? <EyeOff size={16} /> : <Eye size={16} />}</button></div></label></div><div className="mt-5 flex items-center justify-between"><label className="flex items-center gap-2 text-xs font-semibold text-slate-500"><input type="checkbox" checked={remember} onChange={e => setRemember(e.target.checked)} className="accent-[#0f9f92]" />Remember this device</label><button type="button" onClick={() => toast("Password recovery is ready to connect to the authentication service.")} className="text-xs font-bold text-teal hover:text-navy">Forgot password?</button></div><button onClick={submit} disabled={loading} className="mt-8 flex w-full items-center justify-center gap-2 rounded-xl bg-orange px-4 py-3.5 text-xs font-bold text-white shadow-[0_10px_20px_rgba(239,126,55,.2)] transition duration-200 hover:-translate-y-0.5 hover:bg-[#f38b4e] active:scale-[.98] disabled:cursor-wait disabled:opacity-60">{loading ? <RefreshCw className="animate-spin" size={15} /> : <ShieldCheck size={15} />}{loading ? "Checking your access…" : "Sign in securely"}<ArrowRight size={15} /></button><div className="relative my-7 flex items-center"><div className="h-px flex-1 bg-slate-100" /><span className="px-3 text-[10px] font-bold uppercase tracking-[.12em] text-slate-300">New to ShikshaSetu?</span><div className="h-px flex-1 bg-slate-100" /></div><button onClick={onRegister} className="flex w-full items-center justify-center gap-2 rounded-xl border border-[#cfe3e3] bg-[#f7fcfb] px-4 py-3 text-xs font-bold text-teal transition hover:border-teal hover:bg-[#e8f6f3]">Create employee account <ArrowRight size={14} /></button><div className="mt-8 flex items-start gap-2 border-t border-slate-100 pt-5 text-[10px] leading-5 text-slate-400"><ShieldCheck className="mt-0.5 shrink-0 text-teal" size={14} />Your session is protected and ready for JWT storage, Bearer authorization, and 401 redirect handling.</div></div></div></div><div className="mx-auto flex max-w-[1180px] items-center justify-between py-5 text-[10px] text-slate-400"><span>© ShikshaSetu Capability Intelligence</span><span>Need help? Contact your department administrator.</span></div></div>; }
function AuthPage({ mode, onModeChange, onSuccess }: { mode: "login" | "register"; onModeChange: (m: "login" | "register") => void; onSuccess: () => void }) { const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const submit = () => { setError(""); setLoading(true); setTimeout(() => { setLoading(false); if (mode === "login") onSuccess(); else toast("Registration details validated. Connect the submit action to /api/v1/auth/register."); }, 700); }; return <div className="flex min-h-screen items-center justify-center bg-[#f4f7fb] px-5 py-10"><div className="grid w-full max-w-[980px] overflow-hidden rounded-3xl border border-[#dfe7f0] bg-white shadow-[0_20px_60px_rgba(18,48,87,.1)] md:grid-cols-[.8fr_1.2fr]"><div className="relative hidden overflow-hidden bg-navy p-10 text-white md:block"><div className="absolute -right-20 -top-20 h-64 w-64 rounded-full border border-white/10" /><img src="/manus-storage/shikshasetu-bridge-mark_0aca95ee.png" alt="ShikshaSetu" className="mb-12 h-14 w-14" /><Eyebrow>Capability intelligence</Eyebrow><h1 className="font-display text-4xl leading-tight">Bridge the gap between your role and your next capability.</h1><p className="mt-5 text-sm leading-6 text-slate-300">A trusted learning workspace for government employees, powered by explainable assessments and role-aware recommendations.</p><div className="mt-12 space-y-4 text-xs text-slate-300"><div className="flex items-center gap-3"><Check className="text-teal" size={16} />Role-aware competency assessment</div><div className="flex items-center gap-3"><Check className="text-teal" size={16} />Evidence-backed progress</div><div className="flex items-center gap-3"><Check className="text-teal" size={16} />iGOT and NSSTA learning pathways</div></div></div><div className="p-7 md:p-10"><div className="mb-8 flex items-center gap-3 md:hidden"><img src="/manus-storage/shikshasetu-bridge-mark_0aca95ee.png" alt="" className="h-10 w-10 rounded-xl bg-navy p-1" /><div className="font-bold text-navy">ShikshaSetu</div></div><Eyebrow>{mode === "login" ? "Secure employee access" : "Create employee account"}</Eyebrow><h2 className="font-display text-3xl text-navy">{mode === "login" ? "Sign in to your workspace" : "Register your employee profile"}</h2><p className="mt-3 text-sm leading-6 text-slate-500">{mode === "login" ? "Continue your capability journey from the last saved assessment." : "Use your official employee details to connect your role and competency framework."}</p>{error && <div className="mt-5 rounded-xl border border-red-200 bg-red-50 p-3 text-xs text-red-700">{error}</div>}<div className="mt-7 space-y-4">{mode === "register" && <><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-navy">Full name<input className="form-input" placeholder="Ananya Mehta" /></label><label className="text-xs font-bold text-navy">Employee ID<input className="form-input" placeholder="GOV-28417" /></label></div><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-navy">Designation<input className="form-input" placeholder="Statistical Officer" /></label><label className="text-xs font-bold text-navy">Department<input className="form-input" placeholder="Ministry of Statistics" /></label></div><label className="text-xs font-bold text-navy">Professional role<select className="form-input"><option>Statistical Officer</option><option>Programme Officer</option><option>Data Quality Analyst</option></select></label></>}<label className="text-xs font-bold text-navy">Email address<input className="form-input" type="email" placeholder="name@department.gov.in" /></label><label className="text-xs font-bold text-navy">Password<input className="form-input" type="password" placeholder={mode === "register" ? "Minimum 8 characters" : "Enter your password"} /></label></div><button disabled={loading} onClick={submit} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-orange px-4 py-3 text-xs font-bold text-white transition hover:bg-[#f38b4e] disabled:opacity-60">{loading ? <RefreshCw className="animate-spin" size={15} /> : null}{mode === "login" ? "Sign in securely" : "Create employee account"}<ArrowRight size={15} /></button><p className="mt-6 text-center text-xs text-slate-500">{mode === "login" ? "New employee?" : "Already registered?"} <button onClick={() => onModeChange(mode === "login" ? "register" : "login")} className="font-bold text-teal">{mode === "login" ? "Create an account" : "Return to sign in"}</button></p><div className="mt-8 border-t border-slate-100 pt-5 text-[10px] leading-5 text-slate-400">Protected session ready for JWT token storage, Bearer authorization, and 401 redirect handling.</div></div></div></div>; }
function Assessments({ go }: { go: (x: string) => void }) { const [step, setStep] = useState(0); const [rating, setRating] = useState(3); const [submitted, setSubmitted] = useState(false); if (submitted) return <Results go={go} />; const types = ["Self-rating","MCQ knowledge check","Scenario question","Training evidence"]; return <><PageHead eyebrow="Assessment flow" title="AI competency assessment" subtitle="Complete a role-aware assessment across self-rating, knowledge, scenarios, and training evidence." action={<Pill tone="violet">Step {step + 1} of 4</Pill>} /><div className="grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card><div className="mb-7 flex items-center justify-between"><div><Eyebrow>{types[step]}</Eyebrow><h2 className="text-xl font-bold text-navy">{step === 0 ? "Rate your Python capability" : step === 1 ? "Knowledge check" : step === 2 ? "Scenario: validating an official dataset" : "Add training evidence"}</h2></div><div className="text-xs font-bold text-slate-400">{step * 25}% complete</div></div>{step === 0 && <div><p className="text-sm leading-6 text-slate-500">Choose the level that best represents your current ability to prepare, validate, and interpret datasets.</p><div className="mt-8 grid gap-3 sm:grid-cols-5">{[1,2,3,4,5].map(n => <button key={n} onClick={() => setRating(n)} className={`rounded-xl border p-4 text-center transition ${rating === n ? "border-teal bg-[#e8f6f3] text-teal" : "border-slate-200 text-slate-500 hover:border-teal"}`}><div className="text-lg font-extrabold">{n}</div><div className="mt-1 text-[10px] font-bold">{["Awareness","Basic","Working","Advanced","Expert"][n-1]}</div></button>)}</div></div>}{step === 1 && <div className="space-y-3">{["Data validation","Data export","Random sampling","Visual styling"].map((x,i) => <label key={x} className="flex cursor-pointer items-center gap-3 rounded-xl border border-slate-200 p-4 text-sm font-semibold text-navy hover:border-teal"><input type="radio" name="mcq" defaultChecked={i===0} />{x}</label>)}</div>}{step === 2 && <div className="rounded-xl border-l-2 border-orange bg-[#fffaf6] p-5 text-sm leading-6 text-slate-600">A district dataset contains missing values and duplicate records before publication. What should you do first?<div className="mt-4 space-y-2">{["Publish and correct later","Profile and document data quality issues","Remove all incomplete records","Change the reporting period"].map((x,i) => <label key={x} className="flex cursor-pointer items-center gap-3 rounded-lg bg-white p-3 text-xs font-semibold text-navy"><input type="radio" name="scenario" defaultChecked={i===1} />{x}</label>)}</div></div>}{step === 3 && <div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-navy">Training name<input className="form-input" placeholder="Python for Public Data Analysis" /></label><label className="text-xs font-bold text-navy">Provider<input className="form-input" placeholder="iGOT / NSSTA" /></label><label className="text-xs font-bold text-navy">Completion date<input className="form-input" type="date" /></label><label className="text-xs font-bold text-navy">Certificate reference<input className="form-input" placeholder="Certificate ID" /></label></div>}<div className="mt-8 flex justify-between"><button disabled={step===0} onClick={() => setStep(step-1)} className="rounded-xl border border-slate-200 px-4 py-3 text-xs font-bold text-slate-500 disabled:opacity-40">Previous</button>{step < 3 ? <Action onClick={() => setStep(step+1)}>Next question <ArrowRight size={14} /></Action> : <Action onClick={() => setSubmitted(true)}>Submit assessment <Check size={14} /></Action>}</div></Card><Card><Eyebrow>Assessment coverage</Eyebrow><h2 className="text-lg font-bold text-navy">What will be measured</h2><div className="mt-6 space-y-4">{[["Python","Technical",72],["Data Quality","Statistical",64],["Statistical Analysis","Statistical",80]].map(([x,d,v]) => <div key={String(x)}><div className="mb-2 flex justify-between text-xs font-bold"><span className="text-navy">{x}</span><span className="text-slate-400">{d}</span></div><ProgressBar value={Number(v)} /></div>)}</div><div className="mt-8 rounded-xl bg-[#f7fafc] p-4 text-xs leading-5 text-slate-500">Results combine self-assessment, knowledge, scenario performance, and training evidence confidence.</div></Card></div></>; }
function Results({ go }: { go: (x: string) => void }) { return <><PageHead eyebrow="Assessment results" title="Your capability profile moved forward" subtitle="Review the score, confidence, and evidence behind your latest assessment." action={<Pill tone="teal">Completed today</Pill>} /><div className="mb-6 grid gap-4 md:grid-cols-3">{[["Overall capability","3.2 / 5","+0.7 improvement"],["Assessment confidence","0.84","High confidence"],["Competencies assessed","3","Role-aligned"]].map(([a,b,c]) => <Card key={a} className="p-5"><Eyebrow>{a}</Eyebrow><div className="text-3xl font-extrabold text-navy">{b}</div><div className="mt-1 text-xs font-bold text-teal">{c}</div></Card>)}</div><div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Card><div className="mb-6 flex justify-between"><div><Eyebrow>Component breakdown</Eyebrow><h2 className="text-lg font-bold text-navy">How your score was formed</h2></div><LineChart className="text-teal" size={19} /></div>{[["Self-assessment",3.4,85,"bg-teal"],["Knowledge test",3.1,78,"bg-navy"],["Scenario test",3.2,81,"bg-orange"],["Training evidence",3.0,75,"bg-violet"]].map(([x,v,p,c]) => <div className="mb-6" key={String(x)}><div className="mb-2 flex justify-between text-xs font-bold"><span className="text-slate-500">{x}</span><span className="text-navy">{v} / 5 · {p}% confidence</span></div><ProgressBar value={Number(p)} color={String(c)} /></div>)}</Card><Card><Eyebrow>Assessment history</Eyebrow><h2 className="text-lg font-bold text-navy">Recent attempts</h2><div className="mt-6 space-y-3">{[["14 Aug 2026","3.2 / 5","Latest"],["22 May 2026","2.5 / 5","Previous"],["18 Feb 2026","2.1 / 5","Previous"]].map(([d,s,t]) => <div className="flex items-center gap-3 rounded-xl bg-[#f7fafc] p-4" key={d}><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#e7f6f3] text-teal"><ClipboardCheck size={16} /></div><div className="flex-1"><div className="text-xs font-bold text-navy">{d}</div><div className="mt-1 text-[11px] text-slate-400">{t} attempt</div></div><div className="text-sm font-extrabold text-navy">{s}</div></div>)}</div><div className="mt-6"><Action onClick={() => go("Skill Gaps")}>View updated gaps <ArrowRight size={14} /></Action></div></Card></div></>; }
function RoleRequirements() { return <><PageHead eyebrow="Role framework" title="Role Requirements" subtitle="See the competencies required for your Statistical Officer role and how your current profile compares." action={<Pill tone="navy">Statistical Officer · Level 4</Pill>} /><Card><div className="mb-6 flex items-start justify-between"><div><Eyebrow>Assigned role</Eyebrow><h2 className="text-xl font-bold text-navy">Statistical Officer competency framework</h2></div><BriefcaseBusiness className="text-teal" size={21} /></div>{gaps.concat([{name:"Digital Governance",domain:"Digital Governance",current:3.8,required:4,priority:"Low",color:"navy"}]).map(g => <div className="mb-4 rounded-xl border border-slate-100 p-4" key={g.name}><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="text-sm font-bold text-navy">{g.name}</div><div className="mt-1 text-[11px] text-slate-400">{g.domain} · Level definitions 1 Awareness → 5 Expert</div></div><span className="text-xs font-bold text-orange">Gap {(g.required-g.current).toFixed(1)}</span></div><div className="mt-4"><Signal current={g.current} required={g.required} /></div></div>)}</Card></>; }

export default function Home() { const [authenticated, setAuthenticated] = useState(false); const [authMode, setAuthMode] = useState<"login" | "register">("login"); const [active, setActive] = useState("Dashboard"); const [mobileOpen, setMobileOpen] = useState(false); const [isAdministrator] = useState(false); const go = (x: string) => { setActive(x); setMobileOpen(false); }; if (!authenticated) return authMode === "login" ? <LoginPage onSuccess={() => setAuthenticated(true)} onRegister={() => setAuthMode("register")} /> : <AuthPage mode={authMode} onModeChange={setAuthMode} onSuccess={() => setAuthenticated(true)} />; const view = active === "Dashboard" ? <Dashboard go={go} /> : active === "My Competencies" ? <Competencies go={go} /> : active === "Skill Gaps" ? <SkillGaps go={go} /> : active === "Recommendations" ? <Recommendations go={go} /> : active === "Learning" ? <Learning go={go} /> : active === "Assessments" ? <Assessments go={go} /> : active === "Results" ? <Results go={go} /> : active === "Role Requirements" ? <RoleRequirements /> : active === "Learning Evidence" ? <Evidence go={go} /> : active === "Progress" ? <Progress go={go} /> : active === "Profile" ? <ProfileManagement /> : active === "AI Assessment" ? <AIAssessment /> : active === "Quiz Studio" ? <QuizStudio /> : <AdminDashboard go={go} />; return <div className="min-h-screen bg-[#f4f7fb] text-ink"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[264px] flex-col border-r border-[#dfe7f0] bg-white px-5 py-6 transition-transform duration-300 lg:translate-x-0 ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}><div className="flex items-center gap-3 px-2"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-navy shadow-[0_8px_18px_rgba(18,48,87,.18)]"><img src="/manus-storage/shikshasetu-bridge-mark_0aca95ee.png" alt="" className="h-7 w-7" /></div><div><div className="text-[17px] font-extrabold tracking-[-.04em] text-navy">ShikshaSetu</div><div className="text-[9px] font-bold uppercase tracking-[.18em] text-slate-400">Capability Intelligence</div></div><button className="ml-auto lg:hidden" onClick={() => setMobileOpen(false)} aria-label="Close navigation"><X size={18} /></button></div><div className="my-8 px-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Learner workspace</div><nav className="space-y-1">{navItems.map(({label,icon:Icon,badge}) => <button key={label} onClick={() => go(label)} className={`group flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-[13px] font-semibold transition-all ${active===label ? "bg-[#e8f5f3] text-[#087f76] shadow-sm" : "text-slate-500 hover:bg-slate-50 hover:text-navy"}`}>{React.createElement(Icon as React.ElementType, { size: 18 })}<span className="flex-1">{label}</span>{badge && <span className="rounded-full bg-orange px-2 py-0.5 text-[10px] font-bold text-white">{badge}</span>}</button>)}</nav><div className="mt-6 border-t border-slate-100 pt-5"><div className="mb-3 px-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Assessment</div><button onClick={() => go("AI Assessment")} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold ${active === "AI Assessment" ? "bg-[#f0edfc] text-violet" : "text-slate-500 hover:bg-slate-50"}`}><BrainCircuit size={18} />AI competency assessment</button>{isAdministrator && <><div className="mb-3 mt-6 px-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Administration</div><button onClick={() => go("Administrator")} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold ${active === "Administrator" ? "bg-[#eaf0f8] text-navy" : "text-slate-500 hover:bg-slate-50"}`}><ShieldCheck size={18} />Administrator dashboard</button><button onClick={() => go("Quiz Studio")} className={`mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold ${active === "Quiz Studio" ? "bg-[#fff2e8] text-orange" : "text-slate-500 hover:bg-slate-50"}`}><Sparkles size={18} />AI quiz studio</button></>}</div><div className="mt-auto space-y-1"><button onClick={() => toast("Help centre is coming soon.")} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold text-slate-500 hover:bg-slate-50"><CircleHelp size={18} />Help centre</button><button onClick={() => setAuthenticated(false)} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold text-slate-500 hover:bg-[#fff2e8] hover:text-orange"><ArrowRight size={18} className="rotate-180" />Logout</button><button onClick={() => toast("Settings are coming soon.")} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold text-slate-500 hover:bg-slate-50"><Settings size={18} />Settings</button><div className="mt-4 flex items-center gap-3 border-t border-slate-100 px-2 pt-5"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#f6d5b5] text-xs font-bold text-[#7d4725]">AM</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-navy">Ananya Mehta</div><div className="truncate text-[10px] text-slate-400">Statistical Officer</div></div><ChevronDown size={15} className="text-slate-400" /></div></div></aside>{mobileOpen && <button className="fixed inset-0 z-30 bg-navy/30 lg:hidden" onClick={() => setMobileOpen(false)} aria-label="Close navigation overlay" />}<main className="lg:pl-[264px]"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-[#dfe7f0] bg-white/90 px-5 backdrop-blur-xl md:px-9"><div className="flex items-center gap-4"><button className="lg:hidden" onClick={() => setMobileOpen(true)} aria-label="Open navigation"><Menu size={21} /></button><div><div className="hidden text-[10px] font-bold uppercase tracking-[.16em] text-slate-400 md:block">ShikshaSetu workspace</div><div className="text-lg font-bold text-navy">{active}</div></div></div><div className="flex items-center gap-3"><button onClick={() => toast("Search is ready to connect to your backend.")} className="hidden items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-xs text-slate-400 sm:flex"><Search size={15} />Search workspace</button><button onClick={() => toast("You have 2 new updates.")} className="relative rounded-lg p-2 text-slate-500 hover:bg-slate-100" aria-label="Notifications"><Bell size={19} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-orange" /></button><button onClick={() => setAuthenticated(false)} className="hidden rounded-lg border border-slate-200 px-3 py-2 text-[11px] font-bold text-navy md:block">Logout</button><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#f6d5b5] text-[11px] font-bold text-[#7d4725]">AM</div></div></header><div className="mx-auto max-w-[1440px] px-5 py-8 md:px-9 md:py-10">{view}</div></main></div>; }
